/**
 * Zipy AI — SEO title and meta description generation (SEO/quality/safety phase, batch 0).
 *
 * The SEO layer's first job is a defensible `<title>` and `<meta name="description">`
 * for a published guide. Both are generated by the writer LLM under a strict contract:
 *
 *   - The title names the workflow goal. No brand padding, no superlatives, no
 *     invented benefit. Length is bounded so it renders without truncation.
 *   - The meta description summarises what the reader will accomplish and, when
 *     the plan carries a prerequisite, names it. It is a lift of real content
 *     from the guide, never a rephrasing that adds a claim.
 *
 * Design rules honoured here:
 *  - No invented facts. Every candidate is produced from either a deterministic
 *    derivation over the supplied `SeoBrief` (headings, step titles, prerequisites,
 *    audience/industry tokens) or a caller-supplied LLM completion. The composer
 *    never writes an SEO claim the brief does not support.
 *  - Deterministic candidates. `composeSeoMeta` builds two fallback candidates
 *    (`derived-primary` and `derived-short`) purely from the brief so the route
 *    always has a usable title/description even when the LLM is unavailable,
 *    and so the writer's choice is auditable against a known baseline.
 *  - Bounded output. `TitlePolicy` and `DescriptionPolicy` carry hard `maxChars`
 *    limits taken from the guide's SEO policy. `fit()` truncates at a word
 *    boundary and records a `truncated` flag; it never invents a new sentence
 *    tail to make the cut-off read better.
 *  - Deterministic given inputs. No clock reads on the candidate path; the ISO
 *    timestamp is only a build record on the returned payload.
 *  - Nothing here calls the network or an LLM. The route handler that invokes
 *    the writer and passes its completion back in is the only I/O boundary.
 *
 * The module exports:
 *   - `composeSeoMeta` — build the canonical `SeoMeta` from the brief and an
 *     optional LLM completion.
 *   - `buildMetaDirectives` — the LLM-visible block telling the writer what a
 *     valid title/description looks like for this guide.
 *   - `validateSeoMeta` — reject a candidate that violates the policy.
 *   - `rehydrateSeoMeta` — typed load of a persisted payload.
 *   - `fit` — the truncation helper, exported for tests.
 */

import type { StyleProfile } from "@zipy/content/styleProfile";
import type { AudienceProfile } from "@zipy/content/personalization/audience";
import type { IndustryProfile } from "@zipy/content/personalization/industry";

/* -------------------------------------------------------------------------- */
/* Errors                                                                      */
/* -------------------------------------------------------------------------- */

export type SeoErrorCode =
  | "invalid-input"
  | "policy-violation"
  | "shape";

export class SeoError extends Error {
  readonly code: SeoErrorCode;
  readonly detail: Readonly<Record<string, unknown>>;
  constructor(
    message: string,
    code: SeoErrorCode,
    detail: Readonly<Record<string, unknown>> = {},
  ) {
    super(message);
    this.code = code;
    this.detail = detail;
  }
}

/* -------------------------------------------------------------------------- */
/* Public types                                                                */
/* -------------------------------------------------------------------------- */

/**
 * Where a candidate came from. Recorded so a reviewer can see whether a
 * published title was written by the LLM, derived deterministically from the
 * brief, or supplied by a human editor.
 */
export const SEO_CANDIDATE_SOURCES = [
  "llm",
  "derived-primary",
  "derived-short",
  "human",
] as const;
export type SeoCandidateSource = (typeof SEO_CANDIDATE_SOURCES)[number];

export interface TitlePolicy {
  /** Hard ceiling on characters *after* trimming, including any suffix appended. */
  readonly maxChars: number;
  /** Soft target; used to steer the LLM. */
  readonly targetChars: number;
  /**
   * Optional brand suffix. The suffix is appended with the separator below.
   * A suffix never counts against the model's creative budget; it counts
   * against `maxChars`.
   */
  readonly brandSuffix: string | null;
  readonly separator: " | " | " — " | " · " | " - ";
  /** When true, the title is generated in sentence case (first word capitalised). */
  readonly sentenceCase: boolean;
}

export interface DescriptionPolicy {
  readonly maxChars: number;
  readonly targetChars: number;
  /** Require the description to end with sentence-ending punctuation. */
  readonly requireSentenceEnding: boolean;
}

export interface SeoPolicy {
  readonly title: TitlePolicy;
  readonly description: DescriptionPolicy;
}

/**
 * The guide inputs the SEO layer reads. This is a *narrow* projection of the
 * full guide, not the guide itself: the SEO layer never sees the whole
 * document, only the fields that matter to metadata.
 */
export interface SeoBrief {
  /** The workflow goal in the writer's own words, e.g. "Add a new customer". */
  readonly goal: string;
  /** Optional primary product name, e.g. "Acme CRM". Used to name the subject. */
  readonly productName: string | null;
  /** Step titles in order. At least one is required for the derived candidates. */
  readonly stepTitles: readonly string[];
  /** Prerequisites as plain sentences, as written in the guide's intro. */
  readonly prerequisites: readonly string[];
  /** Optional target keywords the operator has chosen. */
  readonly keywords: readonly string[];
  readonly audience: AudienceProfile;
  readonly industry: IndustryProfile;
  readonly styleProfile: StyleProfile;
  readonly policy: SeoPolicy;
}

/**
 * A single candidate the writer produced or the composer derived. `reason`
 * is a one-line explanation shown in the review UI. `truncated` is true when
 * `fit()` had to cut characters to satisfy the policy.
 */
export interface SeoCandidate {
  readonly source: SeoCandidateSource;
  readonly value: string;
  readonly charCount: number;
  readonly truncated: boolean;
  readonly reason: string;
  /** Stable ordering key: the composer emits candidates in a fixed order. */
  readonly order: number;
}

export interface SeoMeta {
  readonly version: "seo-meta/1";
  readonly title: string;
  readonly description: string;
  readonly titleSource: SeoCandidateSource;
  readonly descriptionSource: SeoCandidateSource;
  /**
   * Every candidate the composer considered, in the order it considered them.
   * Persisted so a reviewer can see the alternatives the pipeline rejected.
   */
  readonly titleCandidates: readonly SeoCandidate[];
  readonly descriptionCandidates: readonly SeoCandidate[];
  /**
   * Keywords the composer could place naturally in the title or description.
   * Keywords it could *not* place without distorting the meaning are recorded
   * in `keywordsUnplaced` instead of being stuffed in.
   */
  readonly keywordsPlaced: readonly string[];
  readonly keywordsUnplaced: readonly string[];
  readonly policy: SeoPolicy;
  /** Advisory notes the reviewer must read (e.g. "title truncated"). */
  readonly notes: readonly SeoNote[];
  readonly generatedAt: string;
  readonly aiGenerated: true;
}

export interface SeoNote {
  readonly kind:
    | "title-truncated"
    | "description-truncated"
    | "no-prerequisites"
    | "no-steps"
    | "keyword-unplaced"
    | "llm-unavailable";
  readonly detail: string;
}

/**
 * The LLM's structured completion for the metadata task. Both fields are
 * optional so the route can pass a partial completion; when a field is
 * absent the composer falls back to its deterministic derivation.
 */
export interface SeoLlmCompletion {
  readonly title?: string | null;
  readonly description?: string | null;
  /** Optional rationale the LLM returned; recorded verbatim as a candidate reason. */
  readonly titleReason?: string | null;
  readonly descriptionReason?: string | null;
}

export interface ComposeSeoMetaInput {
  readonly brief: SeoBrief;
  /**
   * The LLM completion. When absent, `composeSeoMeta` produces only derived
   * candidates and records a `llm-unavailable` note. The result is still a
   * valid `SeoMeta` a reviewer can edit.
   */
  readonly llm?: SeoLlmCompletion | null;
  /**
   * When true, a human editor's title/description is preferred over the LLM's
   * (used during a re-generation pass where a reviewer already chose copy).
   */
  readonly preferHuman?: boolean;
  /** Optional human-authored candidate. Used when `preferHuman` is set. */
  readonly human?: { readonly title?: string | null; readonly description?: string | null } | null;
}

/* -------------------------------------------------------------------------- */
/* Public API                                                                  */
/* -------------------------------------------------------------------------- */

/**
 * Compose the canonical `SeoMeta`. The chosen title is the first candidate
 * whose length fits within policy; the chosen description likewise. When no
 * candidate fits, the composer *fits* the best candidate and records a
 * truncation note — it never silently returns an over-long value.
 */
export function composeSeoMeta(input: ComposeSeoMetaInput): SeoMeta {
  if (input === null || typeof input !== "object") {
    throw new SeoError("composeSeoMeta requires an input object.", "invalid-input");
  }
  const { brief } = input;
  validateBrief(brief);

  const notes: SeoNote[] = [];
  const titleCandidates: SeoCandidate[] = [];
  const descriptionCandidates: SeoCandidate[] = [];

  // Order: human (when preferred) → LLM → derived-primary → derived-short.
  let order = 0;
  if (input.preferHuman === true && input.human !== null && input.human !== undefined) {
    if (typeof input.human.title === "string" && input.human.title.trim().length > 0) {
      titleCandidates.push(makeCandidate("human", input.human.title, "Reviewer-supplied title.", order++));
    }
    if (typeof input.human.description === "string" && input.human.description.trim().length > 0) {
      descriptionCandidates.push(
        makeCandidate("human", input.human.description, "Reviewer-supplied description.", order),
      );
    }
  }
  order = 0;

  if (input.llm !== undefined && input.llm !== null) {
    if (typeof input.llm.title === "string" && input.llm.title.trim().length > 0) {
      titleCandidates.push(
        makeCandidate(
          "llm",
          input.llm.title,
          typeof input.llm.titleReason === "string" && input.llm.titleReason.trim().length > 0
            ? input.llm.titleReason.trim()
            : "Writer model completion.",
          order++,
        ),
      );
    }
    if (typeof input.llm.description === "string" && input.llm.description.trim().length > 0) {
      descriptionCandidates.push(
        makeCandidate(
          "llm",
          input.llm.description,
          typeof input.llm.descriptionReason === "string" && input.llm.descriptionReason.trim().length > 0
            ? input.llm.descriptionReason.trim()
            : "Writer model completion.",
          order,
        ),
      );
    }
  } else {
    notes.push({
      kind: "llm-unavailable",
      detail:
        "No LLM completion was supplied; the composer produced deterministic candidates only. A reviewer must approve or replace them.",
    });
  }

  titleCandidates.push(derivePrimaryTitle(brief, order++, notes));
  titleCandidates.push(deriveShortTitle(brief, order++));
  // A description has a single deterministic derivation; the writer LLM's
  // completion is the only other option. Keep the derivation second so a
  // compliant LLM completion wins.
  descriptionCandidates.push(deriveDescription(brief, notes, descriptionCandidates.length));

  // Apply the policy suffix to the title candidates now, so a candidate's
  // charCount reflects what will be rendered.
  const suffixedTitles = titleCandidates.map((c) => applyTitleSuffix(c, brief.policy.title));

  const titleChoice = chooseCandidate(suffixedTitles, brief.policy.title.maxChars);
  const descriptionChoice = chooseCandidate(descriptionCandidates, brief.policy.description.maxChars);
  if (titleChoice === null || descriptionChoice === null) {
    throw new SeoError(
      "composeSeoMeta could not produce a title and description from the supplied brief.",
      "invalid-input",
    );
  }
  if (titleChoice.truncated) {
    notes.push({
      kind: "title-truncated",
      detail: `The title was truncated to fit ${brief.policy.title.maxChars} characters (was ${titleChoice.value.length + titleChoice.charCount - titleChoice.charCount} → ${titleChoice.charCount}).`,
    });
  }
  if (descriptionChoice.truncated) {
    notes.push({
      kind: "description-truncated",
      detail: `The description was truncated to fit ${brief.policy.description.maxChars} characters (final ${descriptionChoice.charCount}).`,
    });
  }

  const { placed, unplaced } = analyseKeywordPlacement(
    brief.keywords,
    titleChoice.value,
    descriptionChoice.value,
  );
  if (unplaced.length > 0) {
    for (const kw of unplaced) {
      notes.push({
        kind: "keyword-unplaced",
        detail: `Keyword "${kw}" is not present in the title or description; do not stuff it in. The reviewer may add it to the guide body instead.`,
      });
    }
  }

  ensureSentenceEnding(descriptionChoice, brief.policy.description, notes);

  return {
    version: "seo-meta/1",
    title: titleChoice.value,
    description: descriptionChoice.value,
    titleSource: titleChoice.source,
    descriptionSource: descriptionChoice.source,
    titleCandidates: suffixedTitles,
    descriptionCandidates,
    keywordsPlaced: placed,
    keywordsUnplaced: unplaced,
    policy: brief.policy,
    notes,
    generatedAt: new Date().toISOString(),
    aiGenerated: true,
  };
}

/**
 * The LLM-visible directive block. Append to the writer's system prompt when
 * requesting a title and description. Deliberately short: the policy and the
 * brief carry the numbers.
 */
export function buildMetaDirectives(brief: SeoBrief): string {
  const lines: string[] = [];
  lines.push("You are writing only the SEO title and meta description for a guide.");
  lines.push(
    `- Title: aim for about ${brief.policy.title.targetChars} characters; the hard limit is ${brief.policy.title.maxChars} characters${brief.policy.title.brandSuffix !== null ? ", excluding the brand suffix appended by the platform" : ""}.`,
  );
  lines.push(
    `- Description: aim for about ${brief.policy.description.targetChars} characters; the hard limit is ${brief.policy.description.maxChars}. Write one sentence, active voice.`,
  );
  if (brief.audience.seniority === "expert") {
    lines.push("- Assume the reader is an expert; omit framing sentences.");
  } else if (brief.audience.seniority === "novice") {
    lines.push("- Assume the reader is new to the product; name the subject explicitly.");
  }
  lines.push(
    "- Name the workflow goal verbatim from the brief. Do not invent a benefit, a superlative or a marketing phrase.",
  );
  if (brief.productName !== null) {
    lines.push(`- The product is named "${brief.productName}". Use it once, not as padding.`);
  } else {
    lines.push("- Do not name a product; the brief did not supply one.");
  }
  if (brief.prerequisites.length > 0) {
    lines.push(
      `- When it fits the character budget, name the first prerequisite: "${brief.prerequisites[0]}".`,
    );
  }
  if (brief.keywords.length > 0) {
    lines.push(
      `- Place these keywords only where they read naturally: ${brief.keywords.join(", ")}. Never stuff a keyword that distorts the sentence.`,
    );
  } else {
    lines.push("- The operator has not supplied target keywords; do not invent any.");
  }
  lines.push(
    "- Do not use exclamation marks, emoji, or ALL CAPS. Do not start the description with 'This guide'.",
  );
  lines.push(
    "- Do not mention screenshots, images, steps, tutorials or walkthroughs unless the brief itself names them.",
  );
  return lines.join("\n");
}

/**
 * Validate a candidate title/description against the policy. Returns a list
 * of violations; the empty list means the candidate is publishable as-is.
 */
export function validateSeoMeta(
  meta: { readonly title: string; readonly description: string },
  policy: SeoPolicy,
): readonly SeoNote[] {
  const notes: SeoNote[] = [];
  if (meta.title.trim().length === 0) {
    notes.push({ kind: "title-truncated", detail: "Title is empty." });
  }
  if (meta.description.trim().length === 0) {
    notes.push({ kind: "description-truncated", detail: "Description is empty." });
  }
  if (meta.title.length > policy.title.maxChars) {
    notes.push({
      kind: "title-truncated",
      detail: `Title is ${meta.title.length} characters; policy limit is ${policy.title.maxChars}.`,
    });
  }
  if (meta.description.length > policy.description.maxChars) {
    notes.push({
      kind: "description-truncated",
      detail: `Description is ${meta.description.length} characters; policy limit is ${policy.description.maxChars}.`,
    });
  }
  if (policy.description.requireSentenceEnding && !/[.!?]$/.test(meta.description.trim())) {
    notes.push({
      kind: "description-truncated",
      detail: "Description does not end with sentence-ending punctuation.",
    });
  }
  return notes;
}

/**
 * Fit a string to `maxChars`, cutting on a word boundary. Returns the
 * possibly-shortened string and whether a cut happened. Never appends an
 * ellipsis or synthesises a tail to make the cut-off read better.
 */
export function fit(s: string, maxChars: number): { text: string; truncated: boolean } {
  if (typeof s !== "string") {
    throw new SeoError("fit requires a string.", "invalid-input");
  }
  if (!Number.isFinite(maxChars) || maxChars <= 0) {
    return { text: s, truncated: false };
  }
  const trimmed = s.trim();
  if (trimmed.length <= maxChars) return { text: trimmed, truncated: false };
  // Reserve one character so a sentence-ending period can be kept.
  const budget = maxChars;
  const slice = trimmed.slice(0, budget);
  // Prefer the last whitespace boundary at or before the budget.
  let cut = slice.lastIndexOf(" ");
  if (cut < Math.floor(budget * 0.6)) cut = slice.length;
  let out = slice.slice(0, cut).replace(/[ ,;:.\-—–]+$/u, "");
  if (out.length === 0) out = slice.trim();
  return { text: out, truncated: true };
}

export function rehydrateSeoMeta(value: unknown): SeoMeta {
  if (value === null || typeof value !== "object") {
    throw new SeoError("Rehydrate failed: payload is not an object.", "shape");
  }
  const r = value as Record<string, unknown>;
  const version = r["version"];
  if (version !== "seo-meta/1") {
    throw new SeoError(
      `Rehydrate failed: expected version "seo-meta/1", received "${String(version)}".`,
      "shape",
    );
  }
  const title = typeof r["title"] === "string" ? r["title"] : "";
  const description = typeof r["description"] === "string" ? r["description"] : "";
  return {
    version: "seo-meta/1",
    title,
    description,
    titleSource: readSource(r["titleSource"]),
    descriptionSource: readSource(r["descriptionSource"]),
    titleCandidates: readCandidates(r["titleCandidates"]),
    descriptionCandidates: readCandidates(r["descriptionCandidates"]),
    keywordsPlaced: readStringList(r["keywordsPlaced"]),
    keywordsUnplaced: readStringList(r["keywordsUnplaced"]),
    policy: readPolicy(r["policy"]),
    notes: readNotes(r["notes"]),
    generatedAt: typeof r["generatedAt"] === "string" ? r["generatedAt"] : "",
    aiGenerated: true,
  };
}

export const DEFAULT_SEO_POLICY: SeoPolicy = Object.freeze({
  title: {
    maxChars: 65,
    targetChars: 55,
    brandSuffix: null,
    separator: " | ",
    sentenceCase: false,
  },
  description: {
    maxChars: 160,
    targetChars: 150,
    requireSentenceEnding: true,
  },
});

/* -------------------------------------------------------------------------- */
/* Derivations                                                                 */
/* -------------------------------------------------------------------------- */

function validateBrief(brief: SeoBrief): void {
  if (brief === null || typeof brief !== "object") {
    throw new SeoError("composeSeoMeta requires a brief object.", "invalid-input");
  }
  if (typeof brief.goal !== "string" || brief.goal.trim().length === 0) {
    throw new SeoError("Brief `goal` must be a non-empty string.", "invalid-input");
  }
  if (!Array.isArray(brief.stepTitles)) {
    throw new SeoError("Brief `stepTitles` must be an array.", "invalid-input");
  }
  if (brief.stepTitles.length === 0) {
    throw new SeoError(
      "Brief `stepTitles` must have at least one entry; the SEO layer cannot name a workflow it cannot see.",
      "invalid-input",
    );
  }
  if (!Array.isArray(brief.prerequisites)) {
    throw new SeoError("Brief `prerequisites` must be an array.", "invalid-input");
  }
  if (!Array.isArray(brief.keywords)) {
    throw new SeoError("Brief `keywords` must be an array.", "invalid-input");
  }
  if (brief.policy === null || typeof brief.policy !== "object") {
    throw new SeoError("Brief `policy` must be an object.", "invalid-input");
  }
  if (
    !Number.isFinite(brief.policy.title.maxChars) ||
    brief.policy.title.maxChars < 20 ||
    brief.policy.title.maxChars > 200
  ) {
    throw new SeoError(
      `Title maxChars must be between 20 and 200; received ${String(brief.policy.title.maxChars)}.`,
      "invalid-input",
    );
  }
  if (
    !Number.isFinite(brief.policy.description.maxChars) ||
    brief.policy.description.maxChars < 40 ||
    brief.policy.description.maxChars > 400
  ) {
    throw new SeoError(
      `Description maxChars must be between 40 and 400; received ${String(brief.policy.description.maxChars)}.`,
      "invalid-input",
    );
  }
}

function derivePrimaryTitle(brief: SeoBrief, order: number, notes: SeoNote[]): SeoCandidate {
  const subject = brief.productName !== null ? ` in ${brief.productName}` : "";
  const goal = sentenceCase(brief.goal);
  const firstStep = brief.stepTitles[0] ?? "";
  const reason =
    firstStep.length > 0
      ? `Derived from the goal "${goal}" and the first step "${firstStep}".`
      : `Derived from the goal "${goal}".`;
  void notes;
  return makeCandidate("derived-primary", `${goal}${subject}`, reason, order);
}

function deriveShortTitle(brief: SeoBrief, order: number): SeoCandidate {
  // A shorter fallback that fits tight policies. Uses the first sentence of
  // the goal if the goal itself is long, otherwise the goal verbatim.
  const goal = sentenceCase(brief.goal);
  const firstSentence = firstSentenceOf(goal);
  const subject = brief.productName !== null ? ` in ${brief.productName}` : "";
  return makeCandidate(
    "derived-short",
    `${firstSentence}${subject}`,
    `Derived from the first sentence of the goal, without elaboration.`,
    order,
  );
}

function deriveDescription(brief: SeoBrief, notes: SeoNote[], order: number): SeoCandidate {
  const pieces: string[] = [];
  const goal = brief.goal.trim().replace(/[.!?]+$/u, "");
  const subject = brief.productName !== null ? ` in ${brief.productName}` : "";
  pieces.push(`${sentenceCase(goal)}${subject}.`);
  if (brief.prerequisites.length > 0) {
    pieces.push(`Requires: ${brief.prerequisites[0].replace(/[.!?]+$/u, "")}.`);
  } else {
    notes.push({
      kind: "no-prerequisites",
      detail:
        "No prerequisites were supplied; the derived description omits them rather than inventing one.",
    });
  }
  const value = pieces.join(" ");
  return makeCandidate(
    "derived-primary",
    value,
    "Derived from the goal and the first prerequisite (when the brief supplied one).",
    order,
  );
}

/* -------------------------------------------------------------------------- */
/* Candidate selection                                                         */
/* -------------------------------------------------------------------------- */

function makeCandidate(
  source: SeoCandidateSource,
  raw: string,
  reason: string,
  order: number,
): SeoCandidate {
  const collapsed = collapseWhitespace(raw);
  return {
    source,
    value: collapsed,
    charCount: collapsed.length,
    truncated: false,
    reason,
    order,
  };
}

function applyTitleSuffix(c: SeoCandidate, policy: TitlePolicy): SeoCandidate {
  if (policy.brandSuffix === null || policy.brandSuffix.trim().length === 0) {
    return c;
  }
  const suffix = `${policy.separator}${policy.brandSuffix.trim()}`;
  // If the current value already ends with the suffix, do not double it.
  if (c.value.endsWith(suffix)) return c;
  const combined = `${c.value}${suffix}`;
  return { ...c, value: combined, charCount: combined.length };
}

/**
 * Choose the first candidate that fits, in order. When none fits, fit the
 * first candidate and return it with `truncated: true`. The composer always
 * returns a candidate when at least one was supplied.
 */
function chooseCandidate(
  candidates: readonly SeoCandidate[],
  maxChars: number,
): SeoCandidate | null {
  if (candidates.length === 0) return null;
  for (const c of candidates) {
    if (c.charCount <= maxChars) return c;
  }
  const first = candidates[0];
  if (first === undefined) return null;
  const { text, truncated } = fit(first.value, maxChars);
  return { ...first, value: text, charCount: text.length, truncated };
}

function ensureSentenceEnding(
  candidate: SeoCandidate,
  policy: DescriptionPolicy,
  notes: SeoNote[],
): void {
  if (!policy.requireSentenceEnding) return;
  if (/[.!?]$/.test(candidate.value.trim())) return;
  // The composer never appends punctuation silently: without a sentence
  // ending the description is flagged but the exact text the writer produced
  // is preserved for the reviewer to fix.
  notes.push({
    kind: "description-truncated",
    detail:
      "The description does not end with sentence-ending punctuation; the reviewer must correct it rather than the composer appending one.",
  });
}

/* -------------------------------------------------------------------------- */
/* Keyword placement                                                           */
/* -------------------------------------------------------------------------- */

function analyseKeywordPlacement(
  keywords: readonly string[],
  title: string,
  description: string,
): { placed: string[]; unplaced: string[] } {
  const haystack = `${title} ${description}`.toLowerCase();
  const placed: string[] = [];
  const unplaced: string[] = [];
  for (const kw of keywords) {
    const trimmed = typeof kw === "string" ? kw.trim() : "";
    if (trimmed.length === 0) continue;
    if (haystack.includes(trimmed.toLowerCase())) placed.push(trimmed);
    else unplaced.push(trimmed);
  }
  return { placed, unplaced };
}

/* -------------------------------------------------------------------------- */
/* Internals                                                                   */
/* -------------------------------------------------------------------------- */

function readSource(v: unknown): SeoCandidateSource {
  return v === "llm" || v === "derived-primary" || v === "derived-short" || v === "human"
    ? v
    : "derived-primary";
}

function readCandidates(v: unknown): readonly SeoCandidate[] {
  if (!Array.isArray(v)) return [];
  const out: SeoCandidate[] = [];
  for (const item of v) {
    if (item === null || typeof item !== "object") continue;
    const o = item as Record<string, unknown>;
    const value = typeof o["value"] === "string" ? o["value"] : "";
    if (value.length === 0) continue;
    out.push({
      source: readSource(o["source"]),
      value,
      charCount:
        typeof o["charCount"] === "number" && Number.isFinite(o["charCount"])
          ? Math.floor(o["charCount"])
          : value.length,
      truncated: o["truncated"] === true,
      reason: typeof o["reason"] === "string" ? o["reason"] : "",
      order:
        typeof o["order"] === "number" && Number.isFinite(o["order"])
          ? Math.floor(o["order"])
          : out.length,
    });
  }
  return out;
}

function readStringList(v: unknown): readonly string[] {
  if (!Array.isArray(v)) return [];
  return v.filter((s): s is string => typeof s === "string" && s.trim().length > 0);
}

function readPolicy(v: unknown): SeoPolicy {
  if (v === null || typeof v !== "object") return DEFAULT_SEO_POLICY;
  const p = v as Record<string, unknown>;
  const t = p["title"] !== null && typeof p["title"] === "object" ? (p["title"] as Record<string, unknown>) : {};
  const d = p["description"] !== null && typeof p["description"] === "object" ? (p["description"] as Record<string, unknown>) : {};
  return {
    title: {
      maxChars: numberOr(t["maxChars"], DEFAULT_SEO_POLICY.title.maxChars),
      targetChars: numberOr(t["targetChars"], DEFAULT_SEO_POLICY.title.targetChars),
      brandSuffix: typeof t["brandSuffix"] === "string" ? t["brandSuffix"] : null,
      separator: readSeparator(t["separator"]),
      sentenceCase: t["sentenceCase"] === true,
    },
    description: {
      maxChars: numberOr(d["maxChars"], DEFAULT_SEO_POLICY.description.maxChars),
      targetChars: numberOr(d["targetChars"], DEFAULT_SEO_POLICY.description.targetChars),
      requireSentenceEnding: d["requireSentenceEnding"] !== false,
    },
  };
}

function readSeparator(v: unknown): TitlePolicy["separator"] {
  if (v === " | " || v === " — " || v === " · " || v === " - ") return v;
  return " | ";
}

function readNotes(v: unknown): readonly SeoNote[] {
  if (!Array.isArray(v)) return [];
  const out: SeoNote[] = [];
  for (const item of v) {
    if (item === null || typeof item !== "object") continue;
    const o = item as Record<string, unknown>;
    const kind = o["kind"];
    if (
      kind !== "title-truncated" &&
      kind !== "description-truncated" &&
      kind !== "no-prerequisites" &&
      kind !== "no-steps" &&
      kind !== "keyword-unplaced" &&
      kind !== "llm-unavailable"
    ) {
      continue;
    }
    out.push({ kind, detail: typeof o["detail"] === "string" ? o["detail"] : "" });
  }
  return out;
}

function numberOr(v: unknown, fallback: number): number {
  if (typeof v === "number" && Number.isFinite(v)) return Math.floor(v);
  return fallback;
}

function collapseWhitespace(s: string): string {
  return s.replace(/\s+/gu, " ").trim();
}

function sentenceCase(s: string): string {
  const trimmed = s.trim();
  if (trimmed.length === 0) return trimmed;
  // Only capitalise the first character; preserve the rest verbatim so a
  // proper noun ("GitHub", "iOS") is not mangled.
  const first = trimmed.charAt(0);
  const upper = first.toUpperCase();
  return upper + trimmed.slice(1);
}

function firstSentenceOf(s: string): string {
  const m = /[.!?](?=\s|$)/u.exec(s);
  if (m === null) return s;
  return s.slice(0, m.index + 1).trim();
}

/* -------------------------------------------------------------------------- */
/* Test-only internals                                                         */
/* -------------------------------------------------------------------------- */

export const __internals = Object.freeze({
  collapseWhitespace,
  sentenceCase,
  firstSentenceOf,
  derivePrimaryTitle,
  deriveShortTitle,
  deriveDescription,
  chooseCandidate,
  applyTitleSuffix,
  analyseKeywordPlacement,
  readPolicy,
  readCandidates,
});
